<script setup lang="ts">
import { t } from '../i18n'
import {computed,ref,watch} from 'vue'
import {GitBranch,ShieldCheck,ChevronDown,CheckCircle2,AlertTriangle,Loader2,ArrowRight} from 'lucide-vue-next'
import {api} from '../api'
import {errorMessage,toast} from '../store'
import type {CaseBundle,Run} from '../types'
const props=defineProps<{bundle:CaseBundle;run:Run|null}>()
const emit=defineEmits<{updated:[];navigate:[target:string]}>()
const open=ref(false),tab=ref('plan'),busy=ref(''),workflow=ref<{waiting_for:string;checkpointed:boolean}|null>(null)
const packageData=computed(()=>props.bundle.case.decision_package?.run_id===props.bundle.case.last_run_id ? props.bundle.case.decision_package : null)
const plan=computed(()=>props.run?.execution_plan?.steps?.length ? props.run.execution_plan : props.bundle.case.status==='analyzing' ? undefined : packageData.value?.execution_plan)
const audit=computed(()=>props.bundle.case.status==='analyzing' ? props.run?.assurance : packageData.value?.assurance || props.run?.assurance)
const lineage=computed(()=>props.bundle.case.status==='analyzing' ? props.run?.evidence_trace : packageData.value?.evidence_trace || props.run?.evidence_trace)
const gaps=computed(()=>props.bundle.case.status==='analyzing' ? props.run?.evidence_gaps || [] : packageData.value?.evidence_gaps || props.run?.evidence_gaps || [])
const steps=computed(()=>new Map((props.run?.events || []).filter(e=>e.tool).map(e=>[e.tool!,e])))
const labels:Record<string,string>={bim_query:t('模型与构件'),spatial_check:t('人员距边线距离'),schedule_query:t('活动时间窗'),activity_conflict_check:t('活动时空冲突'),evidence_check:t('现场资料核对'),site_text_query:t('现场文本核对'),rule_retrieval:t('适用规范'),risk_assessment:t('确定性风险检查')}
const fields:Record<string,string>={guardrail_state:t('临边防护'),guardrail_height_m:t('防护高度'),worker_present:t('人员在场'),drop_height_m:t('坠落高度'),boundary_is_exposed:t('检查边界暴露'),guardrail_fixed:t('防护固定'),guardrail_continuous:t('防护连续'),ppe_confirmed:t('个体防护'),worker_point_m:t('人员标注点')}
const waitingLabels:Record<string,string>={analysis:t('待分析'),evidence:t('待补资料'),review:t('等待人工审核'),implementation:t('等待隐患整改'),after_evidence:t('等待整改后资料'),verification:t('等待人工复核'),complete:t('闭环完成'),rejected:t('审核已拒绝')}
const kindLabels:Record<string,string>={simulation:t('演示模拟'),human_confirmed:t('人工确认'),candidate:t('观察候选')}
function valueText(value:unknown,unit:string|null){return value==null || value==='unknown' ? t('待确认') : typeof value==='boolean' ? value ? t('是') : t('否') : `${({present:t('已设置'),absent:t('未设置')} as Record<string,string>)[String(value)] || String(value)}${unit ? ' '+unit : ''}`}
watch([()=>props.bundle.case.case_id,()=>props.bundle.case.version],async ([caseId])=>{
  try{const result=await api.get<{waiting_for:string;checkpointed:boolean}>(`/cases/${caseId}/workflow`);if(caseId===props.bundle.case.case_id)workflow.value=result}catch{workflow.value=null}
  if(gaps.value.length){open.value=true;tab.value='gaps'}
},{immediate:true})
async function runAction(action:string){
  if(!props.run || busy.value)return
  busy.value=action
  try{await api.post(`/runs/${props.run.run_id}/${action}`);toast(action==='resume' ? t('已从保存的节点继续分析。') : t('已请求取消，当前调用结束后停止。'),'success');emit('updated')}
  catch(cause){toast(errorMessage(cause),'error')}
  finally{busy.value=''}
}
function go(action:string){emit('navigate',({add_evidence:'evidence',confirm_observation:'evidence',resolve_text:'text',edit_activities:'activities',edit_scope:'overview',clarify_task:'overview',review_rules:'knowledge'} as Record<string,string>)[action] || 'evidence')}
</script>
<template>
  <section v-if="plan || run?.runtime" class="card assurance-panel" :aria-label="t('检查计划与证据依据')">
    <button class="assurance-toggle" :aria-expanded="open" @click="open=!open"><GitBranch :size="19" /><strong>{{ t('检查计划与依据') }}</strong><span v-if="gaps.length" class="badge tone-amber">{{ gaps.length }} 项待补</span><span v-else-if="audit?.status==='passed'" class="badge tone-green"><ShieldCheck :size="12" />{{ t('约束校核通过') }}</span><span v-else-if="audit?.status==='blocked'" class="badge tone-amber"><AlertTriangle :size="12" />{{ t('约束校核未通过') }}</span><small v-if="workflow">{{ waitingLabels[workflow.waiting_for] }}</small><ChevronDown :size="16" :class="{rotated:open}" /></button>
    <div v-if="open" class="assurance-content"><nav><button :class="{active:tab==='plan'}" @click="tab='plan'">{{ t('检查计划') }}</button><button :class="{active:tab==='trace'}" @click="tab='trace'">{{ t('证据依据') }}</button><button :class="{active:tab==='audit'}" @click="tab='audit'">{{ t('约束校核') }}</button><button v-if="gaps.length" :class="{active:tab==='gaps'}" @click="tab='gaps'">待补资料 {{ gaps.length }}</button></nav>
      <div v-if="tab==='plan'"><div class="goal-tags"><span v-for="goal in plan?.subtasks" :key="goal.goal_id">{{ goal.title }}</span></div><ol class="plan-steps"><li v-for="step in plan?.steps" :key="step.tool"><CheckCircle2 v-if="['succeeded','cached','succeeded_after_retry'].includes(steps.get(step.tool)?.status || '')" :size="17" class="passed"/><span v-else class="step-dot"/><strong>{{ labels[step.tool] || step.tool }}</strong><span v-if="step.mandatory" class="core-step">{{ t('必需检查') }}</span><small>{{ steps.get(step.tool)?.status==='cached' ? t('复用已校核结果') : ['succeeded','succeeded_after_retry'].includes(steps.get(step.tool)?.status || '') ? t('已完成') : steps.get(step.tool)?.status==='failed' ? t('未完成') : t('待执行') }}</small></li></ol></div>
      <div v-else-if="tab==='trace'" class="lineage-content"><div class="table-scroll"><table><thead><tr><th>{{ t('观察项') }}</th><th>{{ t('记录值') }}</th><th>{{ t('证据') }}</th><th>{{ t('来源') }}</th></tr></thead><tbody><tr v-for="fact in lineage?.facts" :key="fact.id"><td>{{ fields[fact.property] || fact.property }}</td><td>{{ valueText(fact.value,fact.unit) }}</td><td>{{ fact.source_id }}</td><td><span class="source-tag">{{ kindLabels[fact.source_kind] || fact.source_kind }}</span></td></tr></tbody></table></div><div class="rule-links"><div v-for="node in lineage?.nodes.filter(n=>n.kind==='rule')" :key="node.id"><ShieldCheck :size="15" /><strong>{{ node.label }}</strong><span>第 {{ node.source?.pdf_page }} 页 · {{ node.source?.version }}</span></div></div><details><summary>依据关联 {{ lineage?.edges.length || 0 }} 项</summary><ul class="trace-edges"><li v-for="edge in lineage?.edges.filter(e=>['determined_by','computed_from','addresses','retrieved_basis'].includes(e.relation))" :key="`${edge.from}-${edge.to}`"><span>{{ lineage?.nodes.find(n=>n.id===edge.from)?.label }}</span><ArrowRight :size="12" /><span>{{ lineage?.nodes.find(n=>n.id===edge.to)?.label }}</span></li></ul></details></div>
      <div v-else-if="tab==='audit'" class="audit-content"><div v-for="check in audit?.checks" :key="check" class="audit-row"><ShieldCheck v-if="audit?.status==='passed'" :size="16" /><AlertTriangle v-else :size="16" class="audit-warning" /><span>{{ check }}</span></div><div v-for="issue in audit?.issues" :key="issue.code" class="gap-row"><AlertTriangle :size="16" />{{ issue.message }}</div><div class="runtime-summary"><span v-if="workflow?.checkpointed">{{ t('流程节点已保存') }}</span><span v-if="run?.runtime?.recoveries">已恢复 {{ run.runtime.recoveries }} 次</span><span>{{ t('批准与复核由人工确认') }}</span></div></div>
      <div v-else class="gap-content"><div v-for="gap in gaps" :key="gap.gap_id" class="gap-row"><AlertTriangle :size="17" /><div><strong>{{ gap.message }}</strong><small v-if="gap.evidence_id">{{ gap.evidence_id }}</small></div><button class="btn btn-sm" @click="go(gap.action)">{{ t('处理') }}<ArrowRight :size="13" /></button></div></div>
      <footer v-if="run?.runtime?.can_resume || ['queued','running'].includes(run?.status || '')"><button v-if="run?.runtime?.can_resume" class="btn btn-sm" :disabled="!!busy" @click="runAction('resume')"><Loader2 v-if="busy" :size="14" class="spin"/>{{ t('从中断节点继续') }}</button><button v-else class="btn btn-sm" :disabled="!!busy || !!run?.runtime?.cancel_requested" @click="runAction('cancel')">{{ run?.runtime?.cancel_requested ? t('正在停止') : t('取消本次分析') }}</button></footer>
    </div>
  </section>
</template>
<style scoped>
.assurance-panel{margin:0 0 22px;overflow:hidden}.assurance-toggle{display:flex;align-items:center;gap:11px;width:100%;padding:18px 23px;border:0;background:#fff;text-align:left;color:var(--blue)}.assurance-toggle strong{font-size:17px;color:var(--text)}.assurance-toggle small{margin-left:auto;color:var(--muted);font-size:12px}.assurance-toggle>svg:last-child{transition:transform .2s}.rotated{transform:rotate(180deg)}.assurance-content{border-top:1px solid var(--line);padding:0 23px 20px}.assurance-content nav{display:flex;gap:20px;border-bottom:1px solid var(--line);margin-bottom:20px;overflow:auto}.assurance-content nav button{padding:15px 1px;background:none;border:0;border-bottom:2px solid transparent;white-space:nowrap;color:var(--muted);font-size:14px}.assurance-content nav button.active{color:var(--blue);border-bottom-color:var(--blue);font-weight:600}.goal-tags{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:17px}.goal-tags span{background:#f1f5fb;color:#466683;padding:7px 11px;border-radius:7px;font-size:12px}.plan-steps{list-style:none;padding:0;margin:0;display:grid;grid-template-columns:1fr 1fr;gap:10px 24px}.plan-steps li{display:flex;align-items:center;gap:9px;padding:12px 0;border-bottom:1px solid var(--line)}.plan-steps strong{font-size:13px;font-weight:500}.plan-steps small{font-size:11px;color:var(--muted);margin-left:auto}.core-step{font-size:10px;color:var(--muted)}.passed,.audit-row svg{color:var(--green)}.audit-row .audit-warning{color:#936421}.step-dot{height:12px;width:12px;border:2px solid #cad5e2;border-radius:100%;margin:2px}.table-scroll{overflow:auto}.lineage-content table{width:100%;border-collapse:collapse;font-size:13px}.lineage-content th,.lineage-content td{padding:11px 9px;text-align:left;border-bottom:1px solid var(--line);white-space:nowrap}.lineage-content th{background:#f5f8fc;font-weight:500}.source-tag{font-size:11px;padding:4px 7px;background:#f4f6f9;border-radius:5px}.rule-links{display:grid;gap:12px;margin-top:22px}.rule-links>div{display:flex;align-items:center;gap:9px;color:var(--blue)}.rule-links strong{font-size:13px}.rule-links span{font-size:11px;color:var(--muted);margin-left:auto}.lineage-content details{margin-top:18px;font-size:12px;color:var(--muted)}.lineage-content summary{cursor:pointer}.trace-edges{padding:10px 0;list-style:none}.trace-edges li{display:flex;align-items:center;gap:8px;padding:7px 0;font-size:12px;flex-wrap:wrap}.audit-content{display:grid;grid-template-columns:1fr 1fr;gap:14px}.audit-row{display:flex;align-items:center;gap:9px;font-size:13px}.runtime-summary{grid-column:1/-1;display:flex;gap:16px;flex-wrap:wrap;padding-top:17px;border-top:1px solid var(--line);font-size:12px;color:var(--muted)}.gap-content{display:grid;gap:12px}.gap-row{display:flex;align-items:center;gap:12px;padding:15px;background:#fff9ee;border:1px solid #f2e5cd;border-radius:8px;color:#936421}.gap-row strong{font-size:14px;font-weight:500}.gap-row small{display:block;font-size:11px;margin-top:7px}.gap-row button{margin-left:auto}.assurance-content footer{margin-top:18px;border-top:1px solid var(--line);padding-top:16px}@media(max-width:720px){.assurance-toggle{padding:16px;flex-wrap:wrap}.assurance-toggle strong{font-size:16px}.assurance-toggle small{margin-left:0}.assurance-content{padding:0 16px 17px}.plan-steps,.audit-content{grid-template-columns:1fr}.gap-row{align-items:flex-start}.rule-links>div{flex-wrap:wrap}.rule-links span{margin-left:0}}
</style>
